package localchat;
import java.nio.file.*;import java.util.*;import java.util.concurrent.atomic.*;
public final class SelfDevelopmentTest {
 static int checks;static void check(boolean ok,String why){checks++;if(!ok)throw new AssertionError(why);}
 static void git(Path repo,String... args)throws Exception{List<String> cmd=new ArrayList<>(List.of("git","-C",repo.toString()));cmd.addAll(List.of(args));Process p=new ProcessBuilder(cmd).redirectErrorStream(true).start();String text=new String(p.getInputStream().readAllBytes());if(p.waitFor()!=0)throw new AssertionError(text);}
 static Tools.Result call(Tools tools,Map<String,Object> args){return tools.execute(new ChatClient.ToolCall(UUID.randomUUID().toString(),SelfDevelopment.TOOL,args));}
 static Tools host(Path home,Path repo,boolean enabled,String owner){Tools t=new Tools(new Tools.Context(home,home.resolve("skills"),home.resolve("reguli.md"),home.resolve("settings.properties"),Map.of(),System.getProperty("selfdev.python"),new Mcp(),PathMap.none(),true,EnumSet.allOf(Tools.Access.class),(a,b)->Tools.Decision.NO),List.of());return t.memories(new LocalMemories(home,new Properties()),"","Current task",owner).development(repo,enabled);}
 public static void main(String[] a)throws Exception{
  Path root=Files.createTempDirectory(Files.createDirectories(Path.of(System.getProperty("localchat.home"))),"selfdev-");Path home=Files.createDirectories(root.resolve("app")),repo=Files.createDirectories(root.resolve("source"));
  git(repo,"init");git(repo,"config","user.name","Fixture");git(repo,"config","user.email","fixture@example.invalid");
  for(String name:List.of("VERSION","CHANGELOG.md","DEVELOPMENT_STATUS.md","README.md","AGENTS.md","Build.ps1"))Files.writeString(repo.resolve(name),name.equals("VERSION")?"1.0.0":"fixture source");
  git(repo,"add",".");git(repo,"commit","-m","fixture");git(repo,"remote","add","origin",SelfDevelopment.ORIGIN);
  Files.createDirectories(home.resolve("self-development"));Files.copy(Path.of(System.getProperty("selfdev.script")),home.resolve("self-development/service.py"));Files.writeString(home.resolve("settings.properties"),"private settings remain unchanged");
  Tools off=host(home,repo,false,"one");check(off.specs().stream().noneMatch(s->s.name.equals(SelfDevelopment.TOOL)),"development opt-in is off by default");check(call(off,Json.obj("action","status")).isError,"disabled service cannot execute");
  Tools on=host(home,repo,true,"one");check(on.specs().stream().anyMatch(s->s.name.equals(SelfDevelopment.TOOL)),"enabled MBS exposes development capability");
  check(host(home,repo,true,"one").readOnly(true).specs().stream().noneMatch(s->s.name.equals(SelfDevelopment.TOOL)),"read-only never offers source mutation");check(host(home,repo,true,"one").analysisOnly().specs().stream().noneMatch(s->s.name.equals(SelfDevelopment.TOOL)),"analysis agents do not self-program");check(call(host(home,repo,true,"one").readOnly(true),Json.obj("action","begin","goal","a helper")).isError,"read-only blocks direct calls too");
  var begun=call(on,Json.obj("action","begin","goal","Create a generic helper for the current task"));check(!begun.isError,"real Git worktree begin through Java host: "+begun.text);String id=Json.str(Json.parse(begun.text),"session");check(id!=null,"session returned");
  check(!call(on,Json.obj("action","write","session",id,"path","README.md","content","Development-only change")).isError,"write in worktree");check(Files.readString(repo.resolve("README.md")).equals("fixture source"),"original source unchanged");
  check(call(on,Json.obj("action","write","session",id,"path","../settings.properties","content","no")).isError,"traversal blocked");check(call(on,Json.obj("action","write","session",id,"path","src/localchat/SelfDevelopment.java","content","no")).isError,"model cannot edit its own host gate");check(call(on,Json.obj("action","publish","session",id)).isError,"cannot publish untested/versionless change");check(call(on,Json.obj("action","status","session",id,"passed",true)).isError,"model cannot declare tests passed");check(call(host(home,repo,true,"two"),Json.obj("action","status","session",id)).isError,"sessions remain bound to their chat");
  check(!call(on,Json.obj("action","edit","session",id,"path","README.md","find","Development-only change","replace","Exact snippet updated")).isError,"exact edits avoid resending whole source files");check(call(on,Json.obj("action","edit","session",id,"path","README.md","find","missing","replace","bad")).isError,"nonmatching edit never corrupts a file");
  check(Files.readString(home.resolve("settings.properties")).equals("private settings remain unchanged"),"credentials/settings outside editable source");
  LocalChat[] app={null};try(var server=new FeatureTest.Server()){
   FeatureTest.edt(()->{app[0]=AttachmentTest.window(root.resolve("ui"),server.url());Properties config=FeatureTest.field(app[0],"config");String plain=(String)FeatureTest.call(app[0],"plainPrompt",new Class<?>[]{});check(!plain.contains("localchat_develop"),"Normal remains a clean chat");String prompt=(String)FeatureTest.call(app[0],"agentPrompt",new Class<?>[]{Path.class,List.class,PathMap.class},home,List.of(),PathMap.none());check(prompt.contains("skills are not a knowledge boundary"),"general reasoning not bounded by skill coverage");config.setProperty("development.enabled","true");((javax.swing.JComboBox<?>)FeatureTest.field(app[0],"permissionBox")).setSelectedIndex(0);String enabled=(String)FeatureTest.call(app[0],"agentPrompt",new Class<?>[]{Path.class,List.class,PathMap.class},home,List.of(),PathMap.none());check(enabled.contains("localchat_develop")&&enabled.contains("selected provider"),"automatic development uses the selected provider");app[0].dispose();});
  }
  for(String language:I18n.CODES)for(String key:List.of("Dezvoltare automata LocalChat","Activeaza dezvoltarea automata in copie Git","Folderul surselor LocalChat","Testele ruleaza cod local; publicarea foloseste o ramura separata."))check(I18n.keys(language).contains(key),"development settings translated "+language);
  System.out.println("SelfDevelopmentTest: "+checks+" checks passed; actual Git worktree, host gates, owner isolation and reasoning policy");System.exit(0);
 }
}
